import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>الصورة المائلة من أكثر مشاكل الصور شيوعاً. تفتح صورة التقطتها بهاتفك فتكتشف أن الأفق يسير عمودياً، أو مستنداً ممسوحاً يقرأ من أسفل إلى أعلى.</p>\n<p>التدوير والقلب هما الحركتان اللتان تحلان المشكلة. فعند التدوير، تدور الصورة كلها بزاوية محددة، بينما يعكس القلب الصورة من اليسار إلى اليمين أو من الأعلى إلى الأسفل.</p>\n<p>يشرح هذا الدليل الحركتين بكلمات بسيطة. ستتعلم أي الزوايا تستخدم، وكيفية تصحيح صورة سيلفي معكوسة، ولماذا تدور بعض الصور من تلقاء نفسها، وكيفية تقويم صورة مائلة دون فقدان أي جزء منها.</p>\n<h2 id=\"what-rotation-and-flipping-do\">ماذا يفعل التدوير والقلب فعلاً؟</h2>\n<p>عند التدوير، تدور الصورة حول مركزها. فدوران 90 درجة يبدل العرض والارتفاع، فتصبح الصورة الأفقية عمودية، ودوران 180 درجة يقلبها رأساً على عقب.</p>\n<p>أما القلب فشيء آخر. فالقلب الأفقي يعكس الصورة من اليسار إلى اليمين، كما لو نظرت في مرآة، بينما يعكس القلب العمودي الصورة من الأعلى إلى الأسفل.</p>\n<p>ويمكن الجمع بين الحركتين. فيمكنك تدوير صورة 90 درجة ثم قلبها أفقياً، وهذا مفيد عندما تخرج صفحة ممسوحة مائلة ومعكوسة أيضاً.</p>\n<p>ولا تغير أي حركة الألوان أو السطوع أو الحدة. فهي تغير فقط موضع كل بكسل، فتبقى الصورة كما هي في كل شيء آخر.</p>\n<h2 id=\"why-photos-end-up-sideways\">لماذا تخرج الصور مائلة؟</h2>\n<p>تحفظ كاميرات الهواتف الاتجاه كملاحظة داخل الملف، تسمى بيانات EXIF، بدلاً من تدوير البكسلات فعلاً. وبعض التطبيقات تقرأ هذه الملاحظة وبعضها يتجاهلها.</p>\n<p>وعندما يتجاهلها تطبيق، تظهر الصورة مدورة. ولهذا قد تبدو الصورة نفسها جيدة في المعرض ومائلة في نموذج أو تطبيق محادثة أو عارض قديم.</p>\n<p>وتصنع الماسحات المشكلة نفسها بطريقة أخرى. فصفحة تدخل الماسح مقلوبة تخرج مقلوبة، ولا توجد ملاحظة اتجاه تصححها.</p>\n<p>وتضيف صور السيلفي سبباً ثالثاً. فالكاميرات الأمامية تحفظ غالباً معاينة معكوسة، فيقرأ نص قميص بالمقلوب حتى تقلب الصورة أفقياً.</p>\n<h2 id=\"rotation-angles-explained\">زوايا التدوير: 90 و180 ومخصصة</h2>\n<p>تسعون درجة هي الزاوية الأكثر استخداماً. فهي تصحح صورة ملتقطة عمودياً تظهر أفقياً، أو صورة أفقية تظهر كصورة شخصية طويلة.</p>\n<p>ومئة وثمانون درجة تصحح صورة مقلوبة تماماً. ويحدث هذا مع الصفحات الممسوحة، والصور الملتقطة والهاتف مقلوب، وبعض الصور المحفوظة بكاميرات قديمة.</p>\n<p>أما الزوايا المخصصة فتحل الحالات الوسطية. فأفق يميل خمس درجات يحتاج تصحيحاً صغيراً، لا دوراناً كاملاً، والمنزلق يتيح ضبط العدد الدقيق.</p>\n<p>وتدعم أداة CompressMyPic زوايا مخصصة من -180 إلى +180 درجة. كما توسع اللوحة تلقائياً، فلا تفقد صورة مائلة زواياها أبداً بسبب القص.</p>\n<h2 id=\"flip-horizontal-vs-vertical\">قلب أفقي أم قلب عمودي؟</h2>\n<p>القلب الأفقي يعكس الجانبين الأيسر والأيمن. وهو الحل لصورة سيلفي معكوسة، حيث يقرأ النص بالمقلوب وتبقى فرقة الشعر في الجانب الخطأ.</p>\n<p>أما القلب العمودي فيعكس الأعلى والأسفل. وهو أقل شيوعاً، لكنه يصحح صوراً التقطتها كاميرا مثبتة في وضع غير معتاد وهي مقلوبة.</p>\n<p>ويغير القلب معنى الصورة، لا اتجاهها فقط. فصورة مقلوبة للافتة ستقرأ بالمقلوب، وخريطة مقلوبة ستشير في الاتجاه الخطأ.</p>\n<p>استخدم القلب بقصد. دوّر أولاً عندما تكون المشكلة فقط في اتجاه الأعلى، واقلب فقط عندما تكون الصورة معكوسة فعلاً.</p>\n<h2 id=\"exif-orientation-basics\">اتجاه EXIF: لماذا تدور بعض الصور من تلقاء نفسها؟</h2>\n<p>تحمل كل صورة هاتف أو كاميرا بيانات EXIF. وأحد هذه الحقول يسجل كيفية إمساك الكاميرا عند التقاط الصورة.</p>\n<p>وتقرأ المعارض والمتصفحات الحديثة هذا الحقل وتعرض الصورة بشكل صحيح. أما البرامج القديمة وبعض النماذج وبعض الشبكات الاجتماعية فتتجاهله.</p>\n<p>وهذا الفرق يفسر لماذا قد تبدو صورة جيدة على الهاتف وسيئة في كل مكان آخر. فالبكسلات لم تدر أبداً؛ بل تجاهلت الملاحظة التي تصفها.</p>\n<p>وتدوير الصورة في محرر يحل المشكلة إلى الأبد. فالأداة تعيد كتابة البكسلات الحقيقية وتعيد ضبط ملاحظة الاتجاه، فيعرض الملف بشكل صحيح في أي عارض. وللتفاصيل، اقرأ <a href=\"/ar/blog/ittijah-as-sura-wa-tadweer-exif/\">اتجاه الصورة: مشاكل تدوير EXIF مشروحة</a>.</p>\n<h2 id=\"formats-and-quality\">الصيغ والجودة: ماذا يحدث لملفك؟</h2>\n<p>تقبل <a href=\"/ar/tadweer-wa-qalb-as-sura/\">أداة تدوير وقلب الصورة</a> ملفات JPG وPNG وWebP وHEIC وGIF وBMP وSVG حتى 20 MB لكل ملف. ويمكنك الاحتفاظ بالصيغة الأصلية أو التغيير إلى JPG أو PNG أو WebP عند التصدير.</p>\n<p>وتدوير 90 أو 180 درجة شبه دون فقدان لمعظم الصيغ. فالبكسلات يعاد ترتيبها، لا إعادة ترميزها من الصفر، فتبقى الجودة الظاهرة كما هي.</p>\n<p>أما الزوايا المخصصة فمختلفة، لأن الصورة يجب أن يعاد رسمها على لوحة جديدة. وتؤدي الأداة ذلك جيداً، لكن JPG محفوظ مجدداً بجودة منخفضة سيبدو أسوأ قليلاً.</p>\n<p>اختر PNG أو WebP عندما تحتاج أنظف نتيجة، خاصة للقطات الشاشة والرسوم ذات النصوص. أما للصور العادية، فـ JPG بجودة عالية جيد.</p>\n<h2 id=\"batch-rotation\">تدوير صور كثيرة دفعة واحدة</h2>\n<p>إصلاح صورة مائلة سريع، لكن مجلداً كاملاً ممل. وتدعم الأداة التدوير الجماعي وتطبق الدوران نفسه على كل الصور في القائمة دفعة واحدة.</p>\n<p>وهذا مفيد بعد عطلة أو حدث، عندما تشترك عشرات الصور في الاتجاه الخاطئ نفسه. ارفعها معاً، واختر زاوية، ونزلها كلها في ملف ZIP.</p>\n<p>ويطبق الوضع الجماعي التعديل نفسه على كل ملف، لذا يعمل أفضل عندما تكون المشكلة متطابقة في الكل. وإذا احتاج نصف الصور 90 درجة والنصف الآخر 270، قسمها إلى دفعتين.</p>\n<p>ويحتفظ كل ملف باسمه الخاص في تصدير ZIP. ويمكنك أيضاً تنزيل ملف واحد من الدفعة، إذا كان واحد منها فقط يحتاج عناية.</p>\n<h2 id=\"straightening-tilted-photos\">تقويم صورة مائلة دون فقدان الزوايا</h2>\n<p>الأفق المائل مشكلة تدوير صغيرة. فالصورة منحرفة بضع درجات فقط، لكن العين تلاحظها فوراً، خاصة في المناظر الطبيعية وإطلالات البحر.</p>\n<p>اسحب منزلق التدوير بخطوات صغيرة وراقب الأفق وهو يستوي. فغالباً ما تكفي درجة أو درجتان، ويظهر التغيير في المعاينة الحية.</p>\n<p>وعند التدوير بزاوية مخصصة، تظهر فجوات مثلثة في زوايا الإطار. وتوسع الأداة اللوحة ليتسع للصورة المدورة كلها، فلا يضيع أي جزء من الصورة.</p>\n<p>وتملأ هذه الفجوات بلون خلفية أو بالشفافية، حسب الصيغة. ففي تصدير JPG تبقى الزوايا بلون صلب، بينما في PNG تبقى شفافة.</p>\n<h2 id=\"fixing-mirrored-selfies\">كيفية تصحيح سيلفي معكوسة</h2>\n<p>تعرض الكاميرات الأمامية معاينة معكوسة، لأن المرآة تتصرف هكذا. وبعض الهواتف تحفظ النسخة المعكوسة وبعضها يحفظ المصححة.</p>\n<p>وإذا خرجت سيلفي بنص مقلوب، فهي تحتاج قلباً أفقياً. فنقرة واحدة تعكس الصورة مجدداً ويعود النص ليقرأ بشكل صحيح.</p>\n<p>وراجع الصورة كلها قبل القلب، لا النص فقط. فالقلب ينقل أيضاً شامة أو ندبة أو فرقة شعر إلى الجانب الآخر، وهذا يغير مظهر الصورة.</p>\n<p>ولصور الملف الشخصي والصور الشبيهة بوثائق الهوية، تكون النسخة غير المعكوسة عادة هي الصحيحة. فهي تطابق كيف يراك الآخرون، لا كيف ترى نفسك في المرآة.</p>\n<h2 id=\"rotate-vs-crop\">التدوير أم القص: أي تصحيح أولاً؟</h2>\n<p>يحل التدوير والقص مشكلتين مختلفتين، لكنهما يعملان معاً غالباً. دوّر أولاً لتصحيح الاتجاه ثم قص لضبط التأطير.</p>\n<p>فالتدوير بعد القص قد يضيع عملك. فقص صمم لإطار أفقي قد لا يناسب عندما تصبح الصورة عمودية.</p>\n<p>وتقويم صورة ثم قصها مزيج شائع. دوّر بضع درجات لتسوية الأفق ثم قص المثلثات الفارغة التي تركها التدوير في الزوايا.</p>\n<p>وإذا احتجت الأداتين، استخدم <a href=\"/ar/qass-as-suwar/\">أداة قص الصور</a> بعد التدوير. فالقصاص يحافظ على البكسلات المدورة كما هي ويقص فقط الحواف التي تختارها.</p>\n<h2 id=\"privacy-local-processing\">الخصوصية: صورك تبقى على جهازك</h2>\n<p>يحدث التدوير بالكامل في متصفحك. فصورك لا ترفع إلى أي خادم أبداً، وهذا مهم عندما تكون الصور شخصية أو طبية أو مستندات عمل.</p>\n<p>وهذه ميزة حقيقية أمام الأدوات التي تطلب رفع الملف. فمسح جواز سفر أو صورة عائلية لا ينبغي أن يسافر إلى خادم لا تراه لمجرد تقويمه.</p>\n<p>كما تزيل الأداة بيانات موقع EXIF عند التصدير. فصورة مدورة منزلة من الأداة لا تحمل أي سجل لمكان التقاطها.</p>\n<p>وهذا المزيج مفيد لوثائق الهوية والنماذج الممسوحة. فيصحح الاتجاه وتزال بيانات الموقع في خطوة واحدة.</p>\n<h2 id=\"common-mistakes\">أخطاء شائعة عند تدوير الصور</h2>\n<p>الخطأ الأكثر شيوعاً هو التدوير في الاتجاه الخطأ. فصورة تحتاج 90 درجة باتجاه عقارب الساعة ستبدو أسوأ بعد 90 درجة عكس عقارب الساعة، لذا راجع المعاينة قبل التنزيل.</p>\n<p>وخطأ آخر هو القلب عندما يكون الحل الحقيقي هو التدوير. فقلب صورة مائلة يعكسها لكن يتركها مائلة، وتبدو النتيجة أغرب من الأصل.</p>\n<p>كما ينسى الناس أن دوران 90 درجة يبدل العرض والارتفاع. فصورة مقصوصة على شكل لافتة عريضة تصبح صورة شخصية طويلة بعد التدوير، وقد لا تناسب وجهتها بعد ذلك.</p>\n<p>وأخيراً، لا تدور JPG نفسه مرات كثيرة. فكل حفظ يضيف قليلاً من الضرر، لذا دوّر دائماً من الملف الأصلي واحفظ مرة واحدة.</p>\n<h2 id=\"when-to-rotate-vs-reshoot\">متى تدور ومتى تعيد التصوير؟</h2>\n<p>يصحح التدوير الاتجاه، لكنه لا يصلح صورة سيئة. فصورة ضبابية أو سيئة الإضاءة تبقى ضبابية وسيئة الإضاءة بعد أي عدد من الدورانات.</p>\n<p>أعد التصوير عندما يكون الموضوع خارج التركيز أو الإضاءة سيئة. فلا زاوية تدوير ستستعيد التفاصيل التي لم تلتقطها الكاميرا أبداً.</p>\n<p>ودوّر عندما تكون الصورة نفسها جيدة والاتجاه فقط خاطئ. وهذا كل معنى الأداة: تصحيح سريع لصورة جيدة.</p>\n<p>وتنطبق القاعدة نفسها على المستندات. فمسح مستقيم ومقروء يحتاج تدويراً فقط، بينما مسح مائل أو فيه ظلال يستحق إعادة المسح.</p>\n<h2 id=\"rotating-scanned-receipts\">تدوير إيصالات ونماذج ممسوحة</h2>\n<p>غالباً ما تمسح الإيصالات والنماذج الورقية بزوايا غريبة، خاصة عند تمريرها بالماسح على عجل. فإيصال ممسوح مائلاً صعب القراءة وأصعب في الأرشفة.</p>\n<p>صحح الاتجاه قبل حفظ المسح في سجلاتك. فدوران 90 درجة يضع النص عمودياً، وزاوية مخصصة صغيرة تقوم إيصالاً بقي مائلاً قليلاً على الماسح.</p>\n<p>ولسجلات المصروفات، دوّر المسح ثم قص المساحة الفارغة للماسح التي بقيت حوله. والنتيجة ملف نظيف ومقروء، سهل الإرفاق بطلب استرداد.</p>\n<p>وراجع الأرقام بعد التدوير. فإجمالي أو تاريخ يقرأ بوضوح في المعاينة سيبقى واضحاً في التنزيل، بينما مسح ضبابي قد يحتاج مسحاً جديداً بدقة أعلى.</p>\n<h2 id=\"rotation-and-printing\">تدوير الصور للطباعة</h2>\n<p>تتبع الطابعات البكسلات، لا ملاحظة الاتجاه. فصورة تبدو جيدة على الشاشة قد تطبع مائلة إذا كان الملف ما زال يعتمد على بيانات EXIF لعرضه بشكل صحيح.</p>\n<p>صحح الاتجاه قبل إرسال ملف للطباعة. دوّر البكسلات في الأداة، ونزل الملف المصحح، واطبع من تلك النسخة بدلاً من الأصلية.</p>\n<p>وراجع الأبعاد بعد دوران 90 درجة. فالعرض والارتفاع يتبدلان، فتصبح الصورة الأفقية عمودية، وقد يحتاج حجم الورق إلى التغيير أيضاً.</p>\n<p>ولطباعة مؤطرة، دوّر أولاً ثم قص حسب نسبة الإطار. فإجراء الخطوات بهذا الترتيب يحافظ على التكوين سليماً ويتجنب قص الموضوع.</p>\n<h2 id=\"rotation-file-naming\">كيفية تسمية ملفاتك المدورة وتنظيمها</h2>\n<p>تستحق الملفات المدورة أسماء واضحة، خاصة عند تصحيح دفعة كاملة. فاسم مثل beach-rotated.jpg سهل العثور عليه لاحقاً، بينما اسم مثل IMG_4821.jpg لا يقول شيئاً.</p>\n<p>واحفظ الأصول في مجلد منفصل. فالنسخ المدورة هي التي تشارك وترفع، لكن الأصول هي شبكة أمانك إذا احتاج أي تدوير إلى التكرار.</p>\n<p>وعند تدوير دفعة، نزل ZIP واستخرجه في مجلد باسم الحدث أو المشروع. فمجلد منظم يوفر الوقت عندما تحتاج صورة بعد أشهر.</p>\n<p>وتجنب الكتابة فوق الملف الأصلي بالنسخة المدورة. فبمجرد اختفاء الأصل، لا يمكن التراجع عن التدوير دون تحرير جديد، وكل حفظ إضافي يضيف ضرراً إلى JPG.</p>\n<h2 id=\"combining-rotation-with-edits\">دمج التدوير مع تعديلات أخرى</h2>\n<p>غالباً ما يكون التدوير الخطوة الأولى في تحرير أطول، لا الوحيدة. فصورة مائلة قد تحتاج أيضاً إلى قص أو تفتيح أو تغيير حجم قبل أن تصبح جاهزة للمشاركة.</p>\n<p>اعمل بترتيب منطقي: دوّر أولاً، ثم قص، ثم اضبط السطوع أو التباين. فكل خطوة تبني على السابقة، وتغيير الترتيب يهدر الجهد غالباً.</p>\n<p>وبعد التدوير، قد تحتاج صورة إلى ضبط السطوع، لأن لقطة مائلة ملتقطة بإضاءة خافتة تبقى مظلمة حتى وهي مستقيمة. ويتولى <a href=\"/ar/taadil-sutoo-as-sura/\">محرر سطوع الصورة</a> هذه الخطوة.</p>\n<p>وإذا كانت الصورة المدورة كبيرة جداً لوجهتها، غيّر حجمها باستخدام <a href=\"/ar/taghyir-hajm-as-suwar/\">أداة تغيير الحجم</a>. فتغيير الحجم بعد التدوير يحافظ على الأبعاد الصحيحة للاتجاه الجديد.</p>\n<p>وإذا احتاجت صورتك إلى قص بعد التدوير أيضاً، افتح <a href=\"/ar/qass-as-suwar/\">أداة قص الصور</a> بعد ذلك. وللنسخة خطوة بخطوة من هذه العملية، راجع <a href=\"/ar/blog/kayfiyya-tadweer-wa-qalb-as-sura/\">كيفية تدوير صورة أو قلبها</a>، وللمزيد عن <a href=\"/ar/blog/ittijah-as-sura-wa-tadweer-exif/\">اتجاه الصورة وتدوير EXIF</a>.</p>";

